import type { Vec3 } from '../contracts/math';

export interface CameraRaycastHit {
  distance: number;
}

export interface CameraRaycaster {
  cast(origin: Vec3, direction: Vec3, maxDistance: number): CameraRaycastHit | null;
}

export interface CameraCollisionOptions {
  clearance?: number;
  minDistance?: number;
}

const DEFAULT_CLEARANCE = 0.18;
const DEFAULT_MIN_DISTANCE = 0.35;
const EPSILON = 1e-6;

export function resolveCameraPosition(
  target: Vec3,
  desiredPosition: Vec3,
  raycaster: CameraRaycaster,
  options: CameraCollisionOptions = {},
): Vec3 {
  const dx = desiredPosition.x - target.x;
  const dy = desiredPosition.y - target.y;
  const dz = desiredPosition.z - target.z;
  const distance = Math.hypot(dx, dy, dz);

  if (!Number.isFinite(distance) || distance <= EPSILON) return { ...desiredPosition };

  const direction = { x: dx / distance, y: dy / distance, z: dz / distance };
  const hit = raycaster.cast(target, direction, distance);
  if (!hit || !Number.isFinite(hit.distance) || hit.distance < 0 || hit.distance > distance) {
    return { ...desiredPosition };
  }

  const clearance = Math.max(0, options.clearance ?? DEFAULT_CLEARANCE);
  const minDistance = Math.max(0, Math.min(options.minDistance ?? DEFAULT_MIN_DISTANCE, distance));
  const safeDistance = Math.min(distance, Math.max(minDistance, hit.distance - clearance));

  return {
    x: target.x + direction.x * safeDistance,
    y: target.y + direction.y * safeDistance,
    z: target.z + direction.z * safeDistance,
  };
}
