import RAPIER from '@dimforge/rapier3d-compat';
import type { Vec3 } from '../contracts/math';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { CameraRaycastHit, CameraRaycaster } from './CameraCollision';

export class RapierCameraRaycaster implements CameraRaycaster {
  constructor(private readonly physics: PhysicsWorld) {}

  cast(origin: Vec3, direction: Vec3, maxDistance: number): CameraRaycastHit | null {
    if (!Number.isFinite(maxDistance) || maxDistance <= 0) return null;

    const ray = new RAPIER.Ray(origin, direction);
    const hit = this.physics.world.castRay(
      ray,
      maxDistance,
      true,
      undefined,
      undefined,
      undefined,
      undefined,
      (collider) => !collider.isSensor(),
    );

    return hit ? { distance: hit.timeOfImpact } : null;
  }
}
