import { describe, expect, it } from 'vitest';
import type { CameraRaycaster } from './CameraCollision';
import { resolveCameraPosition } from './CameraCollision';

const target = { x: 0, y: 1, z: 0 };
const desired = { x: 0, y: 3, z: 6 };

function raycaster(distance: number | null): CameraRaycaster {
  return { cast: () => (distance === null ? null : { distance }) };
}

describe('resolveCameraPosition', () => {
  it('keeps the desired position when nothing blocks the camera', () => {
    expect(resolveCameraPosition(target, desired, raycaster(null))).toEqual(desired);
  });

  it('moves the camera in front of a blocking obstacle with clearance', () => {
    const result = resolveCameraPosition(target, { x: 0, y: 1, z: 10 }, raycaster(6), { clearance: 0.5 });
    expect(result).toEqual({ x: 0, y: 1, z: 5.5 });
  });

  it('honors minimum camera distance for a hit very close to the target', () => {
    const result = resolveCameraPosition(target, { x: 0, y: 1, z: 5 }, raycaster(0.1), {
      clearance: 0.2,
      minDistance: 0.75,
    });
    expect(result).toEqual({ x: 0, y: 1, z: 0.75 });
  });

  it('falls back to the desired position for invalid raycast distances', () => {
    expect(resolveCameraPosition(target, desired, raycaster(Number.NaN))).toEqual(desired);
    expect(resolveCameraPosition(target, desired, raycaster(-1))).toEqual(desired);
    expect(resolveCameraPosition(target, desired, raycaster(100))).toEqual(desired);
  });

  it('does not raycast when target and desired position coincide', () => {
    let called = false;
    const caster: CameraRaycaster = {
      cast: () => {
        called = true;
        return { distance: 0 };
      },
    };
    expect(resolveCameraPosition(target, target, caster)).toEqual(target);
    expect(called).toBe(false);
  });
});
